import{z as A,x as o,o as E,c as B,q as t,j as r,D as a,d as i,s,S as n}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"过程监督在推理时的应用","description":"","frontmatter":{"title":"过程监督在推理时的应用","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pl-process-supervision-inference.md","filePath":"llm/pl-process-supervision-inference.md","lastUpdated":1791063341000}'),p={name:"llm/pl-process-supervision-inference.md"};function m(d,e,c,h,D,C){const l=o("Mermaid");return E(),B("div",null,[e[2]||(e[2]=t('<h1 id="过程监督在推理时的应用" tabindex="-1">过程监督在推理时的应用 <a class="header-anchor" href="#过程监督在推理时的应用" aria-label="Permalink to &quot;过程监督在推理时的应用&quot;">​</a></h1><div class="epigraph"><p>终局 0/1 告诉你链死没死，不告诉你死在哪一步；把分数贴到每一步上，搜索与剪枝才有地方下手。</p><footer>—— Lightman et al., Let&#39;s Verify Step by Step, 2023；Uesato et al., Solving math word problems with process- and outcome-based feedback, 2022</footer></div><p><a href="/llm/pl-tot-mcts-engineering">上一课</a>把 ToT 与 MCTS 搬进服务，四步循环里唯一没定的是评估器的分数从哪来：模型自评朝流畅假推理剪，终局 0/1 要等链跑完才知道死活，长链上一错整条扔。缺口是过程监督：PRM 给每步一个「这一步是否正确」的分数，剪枝发生在前缀上而不是终点上。本课写 PRM 在推理时的三种用法与服务形态。逐步分数的定义与标签协议见<a href="/llm/process-supervision">过程监督 / PRM</a>，训练侧工序见<a href="/llm/process-reward-training">过程奖励模型训练</a>，这里只补差。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>结果监督的信息在终点才到。<a href="/llm/best-of-n">Best-of-N</a> 在长链上方差很大：一百步里一步算错，\\(R=0\\)，选链者不知道错在哪，只能整条扔；树搜索没有逐步分数就只能靠似然或自评，前者是<a href="/llm/beam-vs-sample">束搜索</a>的目标——似然不等于正确性，后者剪向流畅。PRM 把树的每条边变成可比较的 \\(Q\\)，剪枝、配额、早停才有了统一量纲。但接进推理立刻引出三件事：聚合规则怎么定，打错了怎么办，钱怎么记。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三种用法对应三个接点。其一，独立验证器：并行采 \\(N\\) 条链，PRM 对每条算轨迹分选优。聚合函数定义轨迹目标：取 \\(\\min\\) 是「任何一步小错即否决」，适合证明类任务；取均值容忍小瑕疵，适合开放任务；只取末步等价于只信结论。其二，搜索启发式：上一课四步循环里的评估接 PRM，UCT 配额与剪枝在逐步分数上工作，lookahead 只在分数分不出高下时再花前向。其三，门控与节流：链上分数跌破阈值即砍，或分数停滞即触发反思——PRM 从选链器变成节流阀。</p><p><span class="marginnote">直觉类比：结果监督像只看答题卡给分的阅卷，PRM 像老师盯着草稿纸，在每一步旁边打勾或画叉。搜索据此变成「优先顺着没画叉的草稿继续写」——剪枝第一次可以发生在第 30 步的前缀上，而不必等 100 步写完发现答案是错的再整条扔掉。</span></p><p>服务形态上，PRM 是被搜索并发调用的打分服务：扩展 \\(k\\) 个后继就要 \\(k\\) 次打分，节点数即调用量；同一前缀的逐步分数可缓存复用，兄弟分支只补增量步。打分请求应批量化——单条往返的延迟在树搜索里乘上节点数，会成为新的长尾。</p><p><span class="marginnote">Lightman 等人发布的 PRM800K 含约 80 万条步级标注，量级比结果标签贵一个数量级；推理时用更便宜的代理打分器时，先测它的逐步查准查全，再谈用它省了多少钱。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>两类错误不对称。假阴性——好前缀被判低分——剪掉正确分支，表现为覆盖不足，多花预算可以部分挽回；假阳性——错前缀被判高分——会被搜索放大：束持续保护「写得像证明、中间已错」的链，预算花得越多离真值越远。所以上线顺序是先报逐步检测指标再报端到端准确率；校准差的 PRM 上加大搜索是有害的。聚合规则必须与训练口径一致：训练用末步监督、推理取 \\(\\min\\)，等于换了任务定义。</p><p><span class="marginnote">数字实例（示意）：若 PRM 对错步骤的假阳性率约 10%，搜索每层扩展 5 个后继，到第 3 层前排就几乎必然混进「看着漂亮、中间已错」的链——因为每层都有新机会踩中那 10%。假阴性则相反：剪掉的分支大不了重采样，钱能换回来。这笔不对称账就是「先校准、后加大搜索」的依据。</span></p>',13)),(E(),r(n,null,{default:a(()=>[s(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E4%B8%80%E6%9D%A1%E8%BD%A8%E8%BF%B9%E7%9A%84%E9%80%90%E6%AD%A5%E5%88%86%201.0%200.9%200.2%200.8%22%5D%20--%3E%20MIN%7B%22%E8%81%9A%E5%90%88%E8%A7%84%E5%88%99%E9%80%89%E5%93%AA%E4%B8%AA%22%7D%0A%20%20MIN%20--%3E%7C%22min%20%3D%200.2%22%7C%20A%5B%22%E8%AF%81%E6%98%8E%E7%B1%BB%EF%BC%9A%E4%B8%80%E6%AD%A5%E9%94%99%E5%8D%B3%E5%90%A6%E5%86%B3%22%5D%0A%20%20MIN%20--%3E%7C%22%E5%9D%87%E5%80%BC%E7%BA%A6%200.7%22%7C%20B%5B%22%E5%BC%80%E6%94%BE%E7%B1%BB%EF%BC%9A%E5%AE%B9%E5%BF%8D%E5%B0%8F%E7%91%95%E7%96%B5%22%5D%0A%20%20MIN%20--%3E%7C%22%E5%8F%AA%E7%9C%8B%E6%9C%AB%E6%AD%A5%200.8%22%7C%20C%5B%22%E5%8F%AA%E4%BF%A1%E7%BB%93%E8%AE%BA%EF%BC%8C%E4%B8%AD%E9%97%B4%E9%94%99%E8%AF%AF%E9%9A%90%E5%BD%A2%22%5D%0A%20%20A%20--%3E%20D%5B%22%E5%89%AA%E6%9E%9D%E8%90%BD%E5%9C%A8%E5%87%BA%E9%94%99%E5%89%8D%E7%BC%80%E4%B8%8A%22%5D%0A%20%20B%20--%3E%20D%0A%20%20C%20--%3E%20E%5B%22%E7%AD%89%E4%BB%B7%E4%BA%8E%E9%80%80%E5%9B%9E%E7%BB%93%E6%9E%9C%E7%9B%91%E7%9D%A3%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),(E(),r(n,null,{default:a(()=>[s(l,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20GEN%5B%22%E7%94%9F%E6%88%90%E5%99%A8%E6%8F%90%E8%AE%AE%20k%20%E6%9D%A1%E5%90%8E%E7%BB%A7%22%5D%20--%3E%20PRM%5B%22PRM%20%E6%9C%8D%E5%8A%A1%E6%89%B9%E9%87%8F%E6%89%93%E5%88%86%22%5D%0A%20%20PRM%20--%3E%20AGG%7B%22%E6%8E%A5%E5%93%AA%E4%B8%AA%E6%8E%A5%E7%82%B9%3F%22%7D%0A%20%20AGG%20--%3E%7C%E9%80%89%E9%93%BE%7C%20VER%5B%22%E8%BD%A8%E8%BF%B9%E8%81%9A%E5%90%88%EF%BC%8C%E9%80%89%E6%9C%80%E4%BC%98%E9%93%BE%22%5D%0A%20%20AGG%20--%3E%7C%E5%BC%95%E5%AF%BC%E6%90%9C%E7%B4%A2%7C%20SRCH%5B%22%E6%8E%A5%20UCT%20%E4%B8%8E%E5%89%8D%E7%BC%80%E5%89%AA%E6%9E%9D%22%5D%0A%20%20AGG%20--%3E%7C%E9%97%A8%E6%8E%A7%7C%20GATE%5B%22%E4%BD%8E%E4%BA%8E%E9%98%88%E5%80%BC%E7%A0%8D%E9%93%BE%E6%88%96%E8%A7%A6%E5%8F%91%E5%8F%8D%E6%80%9D%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[i(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=t('<p>账要记全：PRM 前向计入测试时 FLOPs。<a href="/llm/snell-test-time">Snell 等 2024 的综述</a>里计算最优的对比已扣掉这部分——只报生成 token 不报评估开销，成本-质量曲线会整个画歪；上一课的节点闸门应把打分前向与生成前分开计数。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>开放域没有可靠的逐步真值：PRM 在训练分布外的步骤上会自信地错，只能当弱先验，不能当裁判。可核对域里 PRM 也不能当唯一真值：终局应再过独立解析或执行，见<a href="/llm/math-verifier-equivalence">数学验证器与等价</a>与<a href="/llm/code-verifier-unittests">代码验证器：单元测试</a>。分数还要防过优化——生成器学会专门写「打分器喜欢的步骤」，就是<a href="/llm/verifier-bottleneck">验证器瓶颈</a>在推理时的形态，此时换分数比加预算有效。</p><p><span class="marginnote">「过优化」的类比：学生摸清了阅卷老师喜欢「解：」「由题意得」这类格式分，于是每一步都摆出漂亮姿势，题却做错。生成器对 PRM 做的正是同一件事——专门生产「打分器爱看」的步骤。这时继续加搜索预算等于请更多学生照着套路写；换一个打分器（或混入终局执行校验）才是对症的药。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PRM 在推理时三种用法：选链验证器、搜索启发式、门控节流；接点不同，成本与风险不同。</li><li>聚合（min / 积 / 均值 / 末步）定义轨迹目标，必须与训练口径一致，换聚合等于换任务。</li><li>假阴性可挽回，假阳性被搜索放大；先报逐步检测指标，再报端到端准确率。</li><li>PRM 前向计入推理 FLOPs；调用量随节点数线性涨，打分要批量与缓存。</li><li>可核对域终局仍要独立解析或执行；开放域 PRM 只是弱先验。</li><li>出处：Lightman et al., <em>Let&#39;s Verify Step by Step</em>, 2023；Uesato et al., 2022；Snell et al., 2024。</li></ul>',6))])}const u=A(p,[["render",m]]);export{P as __pageData,u as default};
